cat > apps/api/src/shared/error-handler.ts <<'EOF'
import type { FastifyError, FastifyInstance } from 'fastify';
import { errorCodeSchema, type ErrorBody, type ErrorCode } from '@venue/contract';
import { AppError } from './errors';

const codes = errorCodeSchema.enum;

function errorBody(code: ErrorCode, message: string, details?: unknown): ErrorBody {
  return { error: { code, message, details } };
}

function isClientError(statusCode: number | undefined): statusCode is number {
  return statusCode !== undefined && statusCode >= 400 && statusCode < 500;
}

/** Makes the one error body of the API from each error a route throws, and from each error of Fastify. */
export function registerErrorHandler(app: FastifyInstance) {
  app.setErrorHandler((error: FastifyError | AppError, _req, reply) => {
    if (error instanceof AppError) {
      return reply.code(error.statusCode).send(errorBody(error.code, error.message, error.details));
    }
    // Fastify rejects a request itself, for example when the JSON body is malformed.
    if (isClientError(error.statusCode)) {
      return reply.code(error.statusCode).send(errorBody(codes.BAD_REQUEST, error.message));
    }
    app.log.error(error);
    return reply.code(500).send(errorBody(codes.INTERNAL_ERROR, 'Internal server error'));
  });

  app.setNotFoundHandler((req, reply) => {
    return reply.code(404).send(errorBody(codes.NOT_FOUND, `Route ${req.method} ${req.url} not found`));
  });
}
EOF
