import { errorCodes } from '@venue/contract';

const STATUS_BY_CODE = {
  [errorCodes.VALIDATION_ERROR]: 400,
  [errorCodes.NOT_FOUND]: 404,
  [errorCodes.CONFLICT]: 409,
} as const;

type AppErrorCode = keyof typeof STATUS_BY_CODE;

/** An error that a service throws on purpose. The error handler turns it into the error body of the API. */
export type AppError = Error & {
  readonly code: AppErrorCode;
  readonly statusCode: number;
  readonly details?: unknown;
};

function appError(code: AppErrorCode, message: string, details?: unknown): AppError {
  return Object.assign(new Error(message), { code, statusCode: STATUS_BY_CODE[code], details });
}

export function isAppError(error: unknown): error is AppError {
  return error instanceof Error && 'code' in error && typeof error.code === 'string' && Object.hasOwn(STATUS_BY_CODE, error.code);
}

export function validationError(message: string, details?: unknown): AppError {
  return appError(errorCodes.VALIDATION_ERROR, message, details);
}

export function notFoundError(message: string): AppError {
  return appError(errorCodes.NOT_FOUND, message);
}

export function conflictError(message: string): AppError {
  return appError(errorCodes.CONFLICT, message);
}
EOF
