# 03: Appointments web through the contract

**What to build:** The appointment pages and their BFF handlers use the shared contract. One server-only API client calls the API. The Overview page gets the summary through a BFF route. What the user sees does not change.

**Blocked by:** 01 Contract package and typed errors

**Status:** ready-for-agent

- [ ] Only the server-only API client calls the API; no page calls it directly
- [ ] The API URL and the API key come from server-only environment variables; no `NEXT_PUBLIC` key remains
- [ ] The appointment pages and the Overview take their types from the contract; no `any` remains in them
- [ ] The BFF still returns 200 for each API response (ticket 10 changes this)
- [ ] The customers and treatments pages are unchanged
- [ ] `yarn dev` works and the four pages load
'use client';

import Link from 'next/link';
import { useEffect, useState } from 'react';

type Appointment = {
  id: number;
  startsAt: string;
  endsAt: string;
  status: string;
  price: number;
  notes: string | null;
  customer: { id: number; name: string; email: string };
  treatment: { id: number; name: string; durationMin: number };
};

let customerCache: any[] | null = null;

export default function AppointmentsPage() {
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [customers, setCustomers] = useState<any[]>([]);
  const [treatments, setTreatments] = useState<any[]>([]);
  const [status, setStatus] = useState('');
  const [date, setDate] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [treatmentId, setTreatmentId] = useState('');
  const [startsAt, setStartsAt] = useState('');
  const [notes, setNotes] = useState('');

  function load() {
    let url = '/api/appointments?';
    if (status) url += 'status=' + status + '&';
    if (date) url += 'date=' + date;
    fetch(url)
      .then((r) => r.json())
      .then((d) => setAppointments(d));
  }

  useEffect(() => {
    load();
  }, [status, date]);

  useEffect(() => {
    if (customerCache) {
      setCustomers(customerCache);
    } else {
      fetch('/api/customers')
        .then((r) => r.json())
        .then((d) => {
          customerCache = d;
          setCustomers(d);
        });
    }
    fetch('/api/treatments')
      .then((r) => r.json())
      .then((d) => setTreatments(d));
  }, []);

  function create() {
    fetch('/api/appointments', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        customerId: Number(customerId),
        treatmentId: Number(treatmentId),
        startsAt: new Date(startsAt).toISOString(),
        notes,
      }),
    }).then(() => {
      setShowForm(false);
      setCustomerId('');
      setTreatmentId('');
      setStartsAt('');
      setNotes('');
      load();
    });
  }

  function setAppointmentStatus(id: number, newStatus: string) {
    fetch('/api/appointments/' + id, {
      method: 'PATCH',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ status: newStatus }),
    }).then(() => load());
  }

  return (
    <div>
      <h1>Appointments</h1>

      <div className="filters">
        <label>
          Status
          <select value={status} onChange={(e) => setStatus(e.target.value)}>
            <option value="">All</option>
            <option value="pending">Pending</option>
            <option value="confirmed">Confirmed</option>
            <option value="canceled">Cancelled</option>
            <option value="completed">Completed</option>
          </select>
        </label>
        <label>
          Date
          <input type="date" value={date} onChange={(e) => setDate(e.target.value)} />
        </label>
        <button className="secondary" onClick={() => setShowForm(!showForm)}>
          {showForm ? 'Close form' : 'New appointment'}
        </button>
      </div>

      {showForm && (
        <div className="panel" style={{ marginBottom: 20 }}>
          <div className="form-grid">
            <label>
              Customer
              <select value={customerId} onChange={(e) => setCustomerId(e.target.value)}>
                <option value="">Choose a customer</option>
                {customers.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            </label>
            <label>
              Treatment
              <select value={treatmentId} onChange={(e) => setTreatmentId(e.target.value)}>
                <option value="">Choose a treatment</option>
                {treatments.map((t) => (
                  <option key={t.id} value={t.id}>
                    {t.name} ({t.durationMin} min, €{t.price})
                  </option>
                ))}
              </select>
            </label>
            <label>
              Starts at
              <input type="datetime-local" value={startsAt} onChange={(e) => setStartsAt(e.target.value)} />
            </label>
            <label>
              Notes
              <input value={notes} onChange={(e) => setNotes(e.target.value)} />
            </label>
          </div>
          <button onClick={create}>Create appointment</button>
        </div>
      )}

      <table>
        <thead>
          <tr>
            <th>When</th>
            <th>Customer</th>
            <th>Treatment</th>
            <th>Status</th>
            <th>Price</th>
            <th>Notes</th>
            <th></th>
          </tr>
        </thead>
