    expect(startsAtUtc('2026-10-05T11:00:00+02:00')).toBe('2026-10-05T09:00:00.000Z');
  });

  it('is null for a value that is not a time', () => {
    expect(startsAtUtc('next tuesday')).toBeNull();
  });
});
