git log --oneline | head -3 && git status --short | grep -v scratch; cat .scratch/appointment-platform/issues/07-*.md | sed -n 3,20p; mkdir -p apps/api/test/helpers && cat > apps/api/test/helpers/replicas.ts <<'EOF'
import { spawn, spawnSync, type ChildProcess } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import net from 'node:net';
import { tmpdir } from 'node:os';
import path from 'node:path';

const apiRoot = path.resolve(import.meta.dirname, '../..');

export type Replicas = { baseUrls: string[]; stop: () => Promise<void> };

function freePort(): Promise<number> {
  return new Promise((resolve, reject) => {
    const srv = net.createServer();
    srv.listen(0, () => {
      const { port } = srv.address() as net.AddressInfo;
      srv.close(() => resolve(port));
    });
    srv.on('error', reject);
  });
}

async function waitUntilUp(baseUrl: string, child: ChildProcess) {
  const deadline = Date.now() + 20000;
  while (Date.now() < deadline) {
    if (child.exitCode !== null) throw new Error('API process exited before it was ready');
    try {
      const res = await fetch(`${baseUrl}/treatments`);
      if (res.ok) return;
    } catch {
      // not listening yet
    }
    await new Promise((r) => setTimeout(r, 150));
  }
  throw new Error('API did not start within 20s');
}

/**
 * Starts several API processes that share one fresh, seeded SQLite file, as the replicas do in production.
 * It uses the package scripts `db:migrate`, `db:seed` and `start`, as the characterization helper does.
 */
export async function startReplicas(count: number): Promise<Replicas> {
  const dir = mkdtempSync(path.join(tmpdir(), 'venue-replicas-'));
  const env = { ...process.env, DB_PATH: path.join(dir, 'test.db'), NODE_ENV: 'test', TZ: 'UTC' };

  for (const script of ['db:migrate', 'db:seed']) {
    const run = spawnSync('yarn', ['run', script], { cwd: apiRoot, env, encoding: 'utf8' });
    if (run.status !== 0) throw new Error(`yarn run ${script} failed:\n${run.stdout}\n${run.stderr}`);
  }

  const children: ChildProcess[] = [];
  const baseUrls: string[] = [];
  for (let i = 0; i < count; i += 1) {
    const port = await freePort();
    const child = spawn('yarn', ['run', 'start'], {
      cwd: apiRoot,
      env: { ...env, PORT: String(port), SEED_ON_BOOT: 'false' },
      stdio: 'ignore',
      detached: true,
    });
    const baseUrl = `http://127.0.0.1:${port}`;
    await waitUntilUp(baseUrl, child);
    children.push(child);
    baseUrls.push(baseUrl);
  }

  return {
    baseUrls,
    stop: async () => {
      for (const child of children) {
        try {
          process.kill(-(child.pid as number), 'SIGTERM');
        } catch {
          // already gone
        }
      }
      await new Promise((r) => setTimeout(r, 300));
      rmSync(dir, { recursive: true, force: true });
    },
  };
}
EOF
cat > apps/api/test/double-booking.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { startReplicas, type Replicas } from './helpers/replicas';

const ROUNDS = 25;
const REQUESTS_PER_REPLICA = 4;

let replicas: Replicas;
beforeAll(async () => {
  replicas = await startReplicas(2);
});
afterAll(async () => {
  await replicas.stop();
});

function book(baseUrl: string, startsAt: string): Promise<number> {
  return fetch(`${baseUrl}/appointments`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ customerId: 8, treatmentId: 2, startsAt }),
  }).then((res) => res.status);
}

describe('two API replicas on one database', () => {
  it('accept one of the same appointment sent to both at the same time', async () => {
    for (let round = 0; round < ROUNDS; round += 1) {
      // Each round uses its own day, so the rounds do not overlap each other.
      const startsAt = new Date(Date.UTC(2027, 0, 1 + round, 9)).toISOString();
      const requests = replicas.baseUrls.flatMap((baseUrl) =>
        Array.from({ length: REQUESTS_PER_REPLICA }, () => book(baseUrl, startsAt)),
      );
      const statuses = (await Promise.all(requests)).sort();

      const rejected = Array.from({ length: requests.length - 1 }, () => 409);
      expect(statuses, `round ${round}`).toEqual([201, ...rejected]);
    }
  });
});
