import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { startReplicas, type Replicas } from './helpers/replicas';

const ROUNDS = 25;
const REQUESTS_PER_REPLICA = 4;

let replicas: Replicas;
beforeAll(async () => {
  replicas = await startReplicas(2);
});
afterAll(async () => {
  await replicas.stop();
});

function book(baseUrl: string, startsAt: string): Promise<number> {
  return fetch(`${baseUrl}/appointments`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ customerId: 8, treatmentId: 2, startsAt }),
  }).then((res) => res.status);
}

describe('two API replicas on one database', () => {
  it('accept one of the same appointment sent to both at the same time', async () => {
    for (let round = 0; round < ROUNDS; round += 1) {
      // Each round uses its own day, so the rounds do not overlap each other.
      const startsAt = new Date(Date.UTC(2027, 0, 1 + round, 9)).toISOString();
      const requests = replicas.baseUrls.flatMap((baseUrl) =>
        Array.from({ length: REQUESTS_PER_REPLICA }, () => book(baseUrl, startsAt)),
      );
      const statuses = (await Promise.all(requests)).sort();

      const rejected = Array.from({ length: requests.length - 1 }, () => 409);
      expect(statuses, `round ${round}`).toEqual([201, ...rejected]);
    }
  });
});
