import 'server-only';
import { NextResponse } from 'next/server';

// These variables have no NEXT_PUBLIC prefix, so Next keeps them out of the browser bundle.
const API_URL = process.env.API_URL ?? 'http://localhost:4000';
const API_KEY = process.env.API_KEY;

type ProxyOptions = { method?: 'GET' | 'POST' | 'PATCH'; body?: unknown };

/** Sends one request to the API from the server. Returns the JSON body of the API, always with the status 200. */
export async function proxyToApi(path: string, { method = 'GET', body }: ProxyOptions = {}) {
  const headers: Record<string, string> = {};
  if (API_KEY) {
    headers['x-api-key'] = API_KEY;
  }
  if (body !== undefined) {
    headers['content-type'] = 'application/json';
  }
  const res = await fetch(API_URL + path, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  return NextResponse.json(await res.json());
}
import { proxyToApi } from '../../../../lib/api';

type RouteContext = { params: Promise<{ id: string }> };

export async function GET(_req: Request, { params }: RouteContext) {
  const { id } = await params;
  return proxyToApi('/appointments/' + id);
}

export async function PATCH(req: Request, { params }: RouteContext) {
  const { id } = await params;
  return proxyToApi('/appointments/' + id, { method: 'PATCH', body: await req.json() });
}
'use client';

import { useParams } from 'next/navigation';
import { useEffect, useState } from 'react';
import type { Appointment } from '@venue/contract';

// Shareable page: the customer opens it from the confirmation email.
export default function ConfirmationPage() {
  const params = useParams<{ id: string }>();
  const [appointment, setAppointment] = useState<Appointment | null>(null);

  useEffect(() => {
    fetch('/api/appointments/' + params.id)
      .then((r) => r.json())
      .then((d) => setAppointment(d));
  }, [params.id]);

  if (!appointment) return <p>Loading...</p>;

  return (
    <div className="confirmation panel">
      <h1>Your booking</h1>
      <dl>
        <dt>Name</dt>
        <dd>{appointment.customer.name}</dd>
        <dt>Treatment</dt>
        <dd>
          {appointment.treatment.name} ({appointment.treatment.durationMin} min)
        </dd>
        <dt>When</dt>
        <dd>{new Date(appointment.startsAt).toLocaleString()}</dd>
        <dt>Price</dt>
        <dd>€{appointment.price}</dd>
        <dt>Status</dt>
        <dd>
          <span className={'badge ' + appointment.status}>{appointment.status}</span>
        </dd>
      </dl>
    </div>
  );
}
