# 10: Appointments page fixes

**What to build:** The appointments page tells the truth: a rejected booking shows as rejected, the cancelled filter works, and times are in venue time.

**Blocked by:** 03 Appointments web through the contract

**Status:** ready-for-agent

- [ ] Each appointment BFF handler forwards the status code of the API
- [ ] The BFF returns the error body shape of the contract when the API fails
- [ ] The create form shows the error and stays open when the API rejects the booking
- [ ] The status filter sends `cancelled`
- [ ] Times are entered and shown in venue time (Europe/Berlin), not browser time
- [ ] Each of the four fixes is its own `fix` commit

## Comments

**From ticket 03.** The BFF handlers do not parse input with the contract schemas yet. A BFF that rejects a body must return 400, and ticket 03 had to keep the BFF at "always 200". Add the input parse here, together with the status forwarding: parse the body of `POST` and `PATCH` with the contract schema, and return 400 with the contract error body when it fails.

'use client';

import Link from 'next/link';
import { useEffect, useState } from 'react';
import type { Appointment, AppointmentStatus } from '@venue/contract';

// The customer and treatment lists have no schema of their own yet. They return the shapes that an appointment embeds.
type Customer = Appointment['customer'];
type Treatment = Appointment['treatment'];

let customerCache: Customer[] | null = null;

export default function AppointmentsPage() {
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [treatments, setTreatments] = useState<Treatment[]>([]);
  const [status, setStatus] = useState('');
  const [date, setDate] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [treatmentId, setTreatmentId] = useState('');
  const [startsAt, setStartsAt] = useState('');
  const [notes, setNotes] = useState('');

  function load() {
    let url = '/api/appointments?';
    if (status) url += 'status=' + status + '&';
    if (date) url += 'date=' + date;
    fetch(url)
      .then((r) => r.json())
      .then((d) => setAppointments(d));
  }

  useEffect(() => {
    load();
  }, [status, date]);

  useEffect(() => {
    if (customerCache) {
      setCustomers(customerCache);
    } else {
      fetch('/api/customers')
        .then((r) => r.json())
        .then((d) => {
          customerCache = d;
          setCustomers(d);
        });
    }
    fetch('/api/treatments')
      .then((r) => r.json())
      .then((d) => setTreatments(d));
  }, []);

  function create() {
    fetch('/api/appointments', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        customerId: Number(customerId),
        treatmentId: Number(treatmentId),
        startsAt: new Date(startsAt).toISOString(),
        notes,
      }),
    }).then(() => {
      setShowForm(false);
      setCustomerId('');
      setTreatmentId('');
      setStartsAt('');
      setNotes('');
      load();
    });
  }

  function setAppointmentStatus(id: number, newStatus: AppointmentStatus) {
    fetch('/api/appointments/' + id, {
      method: 'PATCH',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ status: newStatus }),
    }).then(() => load());
  }

  return (
    <div>
      <h1>Appointments</h1>

      <div className="filters">
        <label>
          Status
          <select value={status} onChange={(e) => setStatus(e.target.value)}>
            <option value="">All</option>
            <option value="pending">Pending</option>
            <option value="confirmed">Confirmed</option>
            <option value="canceled">Cancelled</option>
            <option value="completed">Completed</option>
          </select>
        </label>
        <label>
          Date
          <input type="date" value={date} onChange={(e) => setDate(e.target.value)} />
        </label>
        <button className="secondary" onClick={() => setShowForm(!showForm)}>
          {showForm ? 'Close form' : 'New appointment'}
        </button>
      </div>

      {showForm && (
        <div className="panel" style={{ marginBottom: 20 }}>
          <div className="form-grid">
            <label>
              Customer
              <select value={customerId} onChange={(e) => setCustomerId(e.target.value)}>
                <option value="">Choose a customer</option>
                {customers.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            </label>
            <label>
              Treatment
              <select value={treatmentId} onChange={(e) => setTreatmentId(e.target.value)}>
