# 12: Create and list staff members

**What to build:** A staff member can be created and listed, from the database to the page. The module has the same shape as the appointments module.

**Blocked by:** 02 Appointments API as a layered module; 03 Appointments web through the contract

**Status:** ready-for-agent

- [ ] A generated migration creates the staff table: id, name, email, active (default true), createdAt; with a unique index on the lower-case email
- [ ] `POST /staff` with name and email returns 201 and `{ id, name, email, active, createdAt }`, with `createdAt` in ISO 8601
- [ ] `GET /staff` returns an array ordered by name
- [ ] The email is stored and returned as sent, trimmed
- [ ] A second staff member whose email differs only in letter case returns 409
- [ ] A blank name or a malformed email returns 400
- [ ] The repository maps the unique-constraint error of that index to the conflict error
- [ ] The module has routes, a service, a repository and a mapper, and its schemas are in the contract
- [ ] BFF routes, a list page, a create form and a navigation link exist
- [ ] Tests cover each status code above through HTTP
import type { FastifyInstance } from 'fastify';
import {
  createAppointmentBodySchema,
  listAppointmentsQuerySchema,
  updateAppointmentBodySchema,
} from '@venue/contract';
import { parseInput } from '../../shared/validation';
import * as service from './appointments.service';

type IdParams = { Params: { id: string } };

export function registerAppointmentsRoutes(app: FastifyInstance) {
  app.get('/appointments', (req) => {
    return service.listAppointments(parseInput(listAppointmentsQuerySchema, req.query));
  });

  app.get('/appointments/summary', () => {
    return service.getAppointmentSummary();
  });

  app.get<IdParams>('/appointments/:id', (req) => {
    return service.getAppointment(Number(req.params.id));
  });

  app.post('/appointments', (req, reply) => {
    const appointment = service.createAppointment(parseInput(createAppointmentBodySchema, req.body));
    return reply.code(201).send(appointment);
  });

  app.patch<IdParams>('/appointments/:id', (req) => {
    const id = Number(req.params.id);
    // An unknown appointment is a 404 even when the body is invalid, so the lookup comes first.
    service.getAppointment(id);
    return service.updateAppointment(id, parseInput(updateAppointmentBodySchema, req.body));
  });
}
import { errorCodes, type ErrorCode } from '@venue/contract';

export class AppError extends Error {
  constructor(
    readonly statusCode: number,
    readonly code: ErrorCode,
    message: string,
    readonly details?: unknown,
  ) {
    super(message);
  }
}

export class ValidationError extends AppError {
  constructor(message: string, details?: unknown) {
    super(400, errorCodes.VALIDATION_ERROR, message, details);
  }
}

export class NotFoundError extends AppError {
  constructor(message: string) {
    super(404, errorCodes.NOT_FOUND, message);
  }
}

export class ConflictError extends AppError {
  constructor(message: string) {
    super(409, errorCodes.CONFLICT, message);
  }
}
import { sql, type SQL } from 'drizzle-orm';
import { index, sqliteTable, integer, text, real } from 'drizzle-orm/sqlite-core';

export const customers = sqliteTable('customers', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  name: text('name').notNull(),
  email: text('email').notNull(),
  phone: text('phone'),
  createdAt: text('created_at').notNull(),
});

export const treatments = sqliteTable('treatments', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  name: text('name').notNull(),
  category: text('category').notNull(),
  price: real('price').notNull(),
  durationMin: integer('duration_min').notNull(),
});

// A legacy appointment stores `starts_at` as `YYYY-MM-DD HH:mm` in venue time (Europe/Berlin). This expression
// converts it to UTC with the EU daylight-saving rule: summer time runs from 02:00 on the last Sunday of March
// to 03:00 on the last Sunday of October. Each other value is parsed as ISO 8601 and written in UTC.
// Two hours are special. 02:00 to 02:59 does not exist on the day in March, and occurs twice on the day in
// October. Both are read as summer time.
// See docs/adr/0002-generated-column-for-start-time.md before you change it.
const startsAtUtcExpression = (startsAt: SQL): SQL => sql`CASE WHEN ${startsAt} GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9] [0-9][0-9]:[0-9][0-9]' THEN strftime('%Y-%m-%dT%H:%M:%fZ', ${startsAt}, CASE WHEN ${startsAt} >= date(substr(${startsAt}, 1, 4) || '-04-01', 'weekday 0', '-7 days') || ' 02:00' AND ${startsAt} < date(substr(${startsAt}, 1, 4) || '-11-01', 'weekday 0', '-7 days') || ' 03:00' THEN '-2 hours' ELSE '-1 hours' END) ELSE strftime('%Y-%m-%dT%H:%M:%fZ', ${startsAt}) END`;

export const appointments = sqliteTable(
  'appointments',
  {
    id: integer('id').primaryKey({ autoIncrement: true }),
    customerId: integer('customer_id').notNull(),
    treatmentId: integer('treatment_id').notNull(),
    startsAt: text('starts_at').notNull(),
    status: text('status').notNull(),
    price: real('price').notNull(),
    notes: text('notes'),
    createdAt: integer('created_at').notNull(),
    reminderSentAt: integer('reminder_sent_at'),
    startsAtUtc: text('starts_at_utc').generatedAlwaysAs((): SQL => startsAtUtcExpression(sql`${appointments.startsAt}`), {
      mode: 'virtual',
    }),
  },
  (table) => [index('appointments_starts_at_utc_idx').on(table.startsAtUtc)],
);
