  const id = staffIdParamSchema.safeParse((await params).id);
  if (!id.success) {
    return notFound();
  }
  const body = await parseBody(req, updateStaffBodySchema);
  if ('response' in body) {
    return body.response;
  }
  return forwardToApi('/staff/' + id.data, { method: 'PATCH', body: body.data });
}
