 6 │ // Fails when `schema.ts` has a change that no migration covers.
 7 │ //
 8 │ // It runs `drizzle-kit generate`, the command behind `yarn db:generate`, against a copy of the migrations folder, and
 9 │ // looks for a new file. Two other ways do not work: `drizzle-kit check` does not read `schema.ts`, and `generate`
10 │ // exits with 0 for each result. So the check passes only on the message that says nothing changed.
11 │ const NOTHING_TO_MIGRATE = 'nothing to migrate';
12 │ const GENERATE_TIMEOUT = 60 * 1000;
13 │ 
14 │ const apiRoot = path.resolve(import.meta.dirname, '../..');
15 │ const schemaOption = process.argv.indexOf('--schema');
16 │ // The tests give another schema file. The default is the real one.
17 │ const schema = schemaOption === -1 ? './src/db/schema.ts' : process.argv[schemaOption + 1];
18 │ 
19 │ function filesIn(dir: string): string[] {
20 │   return readdirSync(dir, { recursive: true }).map(String).sort();
21 │ }
22 │ 
23 │ /** Runs the check. Returns `true` when the migrations cover the schema. */
24 │ function migrationsCoverSchema(): boolean {
25 │   // drizzle-kit needs a relative path, so the copy is inside the API package.
26 │   const copy = mkdtempSync(path.join(apiRoot, '.db-check-'));
27 │   try {
28 │     cpSync(path.join(apiRoot, 'drizzle'), copy, { recursive: true });
29 │     const before = filesIn(copy);
30 │     const out = `./${path.relative(apiRoot, copy)}`;
31 │     const run = spawnSync('yarn', ['drizzle-kit', 'generate', '--dialect', 'sqlite', '--schema', schema, '--out', out], {
32 │       cwd: apiRoot,
33 │       encoding: 'utf8',
34 │       // No input: drizzle-kit asks a question for a rename, and the check must not wait for an answer.
35 │       stdio: ['ignore', 'pipe', 'pipe'],
36 │       timeout: GENERATE_TIMEOUT,
37 │     });
38 │     const output = `${run.stdout ?? ''}${run.stderr ?? ''}`;
39 │     const added = filesIn(copy).filter((file) => !before.includes(file));
40 │ 
41 │     if (added.length > 0) {
42 │       console.error('db:check failed: schema.ts has a change that no migration covers.');
43 │       console.error('Run `yarn db:generate`, read the SQL, and commit it. The missing migration is:\n');
44 │       for (const file of added.filter((name) => name.endsWith('.sql'))) {
45 │         console.error(readFileSync(path.join(copy, file), 'utf8'));
46 │       }
47 │       return false;
48 │     }
49 │     if (run.status === 0 && output.includes(NOTHING_TO_MIGRATE)) {
50 │       console.log('db:check passed: the migrations cover schema.ts.');
51 │       return true;
52 │     }
53 │     console.error('db:check failed: drizzle-kit did not give a clear result.');
54 │     console.error('A renamed column or table has this effect, because drizzle-kit asks a question about it.');
55 │     console.error('Run `yarn db:generate` in a terminal and answer the question. The output of drizzle-kit was:\n');
