 2 │ import { NextResponse } from 'next/server';
 3 │ import { errorCodes, type ErrorBody, type ErrorCode } from '@venue/contract';
 4 │ 
 5 │ // These variables have no NEXT_PUBLIC prefix, so Next keeps them out of the browser bundle.
 6 │ const API_URL = process.env.API_URL ?? 'http://localhost:4000';
 7 │ const API_KEY = process.env.API_KEY;
 8 │ 
 9 │ /** The part of a contract schema that this file uses. */
10 │ type Schema<T> = {
11 │   safeParse(input: unknown): { success: true; data: T } | { success: false; error: { issues: unknown[] } };
12 │ };
13 │ 
14 │ type RequestOptions = { method?: 'GET' | 'POST' | 'PATCH' | 'DELETE'; body?: unknown };
15 │ 
16 │ /** Sends one request to the API from the server. Returns the status code and the JSON body of the API. */
17 │ export async function requestApi(path: string, { method = 'GET', body }: RequestOptions = {}) {
18 │   const headers: Record<string, string> = {};
19 │   if (API_KEY) {
20 │     headers['x-api-key'] = API_KEY;
21 │   }
22 │   if (body !== undefined) {
23 │     headers['content-type'] = 'application/json';
24 │   }
25 │   const res = await fetch(API_URL + path, {
26 │     method,
27 │     headers,
28 │     body: body === undefined ? undefined : JSON.stringify(body),
29 │   });
30 │   // A 204 answer has no body.
31 │   const json: unknown = res.status === 204 ? null : await res.json();
32 │   return { status: res.status, body: json };
33 │ }
34 │ 
35 │ /** Sends one request to the API from the server. Returns the JSON body of the API, always with the status 200. */
36 │ export async function proxyToApi(path: string, options: RequestOptions = {}) {
37 │   const { body } = await requestApi(path, options);
38 │   return NextResponse.json(body);
39 │ }
40 │ 
41 │ type ErrorResponseOptions = { status: number; code: ErrorCode; message: string; details?: unknown };
42 │ 
43 │ /** Makes an error response with the error body of the contract. */
44 │ export function errorResponse({ status, code, message, details }: ErrorResponseOptions) {
45 │   const body: ErrorBody = { error: { code, message, details } };
46 │   return NextResponse.json(body, { status });
47 │ }
48 │ 
49 │ /** Sends one request to the API from the server. Forwards the status code and the JSON body of the API. */
50 │ export async function forwardToApi(path: string, options: RequestOptions = {}) {
51 │   try {
52 │     const { status, body } = await requestApi(path, options);
53 │     if (status === 204) {
54 │       return new NextResponse(null, { status });
55 │     }
56 │     return NextResponse.json(body, { status });
57 │   } catch {
58 │     // The API did not answer, or its answer was not JSON.
59 │     return errorResponse({ status: 502, code: errorCodes.INTERNAL_ERROR, message: 'The API is not available' });
60 │   }
61 │ }
62 │ 
63 │ /** Parses the JSON body of a request with a contract schema. Returns the 400 response when the body is not valid. */
64 │ export async function parseBody<T>(req: Request, schema: Schema<T>): Promise<{ data: T } | { response: NextResponse }> {
65 │   const json: unknown = await req.json().catch(() => undefined);
66 │   const result = schema.safeParse(json);
67 │   if (!result.success) {
68 │     const details = result.error.issues;
69 │     return { response: errorResponse({ status: 400, code: errorCodes.VALIDATION_ERROR, message: 'Invalid input', details }) };
70 │   }
71 │   return { data: result.data };
72 │ }
73 │ 
74 │ /** Parses the query string of a request with a contract schema. Returns the 400 response when it is not valid. */
75 │ export function parseQuery<T>(req: Request, schema: Schema<T>): { data: T } | { response: NextResponse } {
76 │   const params = new URL(req.url).searchParams;
77 │   const query: Record<string, string | string[]> = {};
78 │   for (const key of new Set(params.keys())) {
79 │     // A parameter that is given twice becomes a list, which no schema accepts. The API does the same.
80 │     const values = params.getAll(key);
81 │     query[key] = values.length === 1 ? values[0] : values;
82 │   }
83 │   const result = schema.safeParse(query);
84 │   if (!result.success) {
85 │     const details = result.error.issues;
86 │     return { response: errorResponse({ status: 400, code: errorCodes.VALIDATION_ERROR, message: 'Invalid input', details }) };
87 │   }
88 │   return { data: result.data };
89 │ }
