 1 │ import { NextResponse } from 'next/server';
 2 │ import { appointmentIdParamSchema, errorCodes, publicAppointmentSchema, type ErrorBody } from '@venue/contract';
 3 │ import { requestApi } from '../../../../../lib/api';
 4 │ 
 5 │ type RouteContext = { params: Promise<{ id: string }> };
 6 │ 
 7 │ const notFound: ErrorBody = { error: { code: errorCodes.NOT_FOUND, message: 'Appointment not found' } };
 8 │ const unavailable: ErrorBody = { error: { code: errorCodes.INTERNAL_ERROR, message: 'Appointment not available' } };
 9 │ 
10 │ // The customer opens the confirmation page, so this route returns only what a customer can see.
11 │ // It sends no body of the API as it is: each response is the public schema or a fixed error.
12 │ export async function GET(_req: Request, { params }: RouteContext) {
13 │   const id = appointmentIdParamSchema.safeParse((await params).id);
14 │   if (!id.success) {
15 │     return NextResponse.json(notFound, { status: 404 });
16 │   }
17 │   // A rejected request means that the API did not answer, or that its answer was not JSON.
18 │   const { status, body } = await requestApi('/appointments/' + id.data).catch(() => ({ status: 502, body: undefined }));
19 │   if (status === 404) {
20 │     return NextResponse.json(notFound, { status: 404 });
21 │   }
22 │   const appointment = publicAppointmentSchema.safeParse(body);
23 │   if (status !== 200 || !appointment.success) {
24 │     return NextResponse.json(unavailable, { status: 502 });
25 │   }
26 │   return NextResponse.json(appointment.data);
27 │ }
