  console.log(same ? 'same' : 'DIFF', o.status, n.status, c[0], c[1], JSON.stringify(c[2] ?? ''), Array.isArray(o.body) ? 'ids=' + o.body.map(x => x.id) : '');
}
// concurrency: 6 identical bookings at once
for (const base of [OLD, NEW]) {
  const rs = await Promise.all(Array.from({length: 6}, () => call(base, P({customerId:4,treatmentId:2,startsAt:'2026-11-20T09:00:00.000Z'}))));
  console.log(base, 'concurrent', rs.map(r => r.status + (r.status === 409 ? ':' + JSON.stringify(r.body).slice(0,70) : '')).join(' | '));
}
console.log('diffs', diffs);

