// Adds one appointment whose customer row is missing and one whose treatment row is missing to both databases,
// then sends the same reads and updates to the API before the refactor (4101) and after it (4102).
import { execFileSync } from 'node:child_process';
import path from 'node:path';

const here = import.meta.dirname;
const insert =
  "INSERT INTO appointments (id, customer_id, treatment_id, starts_at, status, price, notes, created_at) VALUES " +
  "(101, 999, 1, '2026-12-01T09:00:00.000Z', 'confirmed', 10, NULL, 1), " +
  "(102, 1, 999, '2026-12-02T09:00:00.000Z', 'confirmed', 10, NULL, 2);";
for (const name of ['old', 'new']) {
  execFileSync('sqlite3', [path.join(here, name + '.db'), insert]);
}

async function call(base, method, url, body) {
  const init = { method, headers: {} };
  if (body !== undefined) {
    init.body = JSON.stringify(body);
    init.headers['content-type'] = 'application/json';
  }
  const res = await fetch(base + url, init);
  const text = await res.text();
  let json;
  try {
    json = JSON.parse(text);
  } catch {
    json = text;
  }
  const short = Array.isArray(json)
    ? `[${json.length} items] 101: ${JSON.stringify(json.find((a) => a.id === 101) ?? 'absent').slice(0, 200)} | 102: ${JSON.stringify(json.find((a) => a.id === 102) ?? 'absent').slice(0, 200)}`
    : JSON.stringify(json).slice(0, 260);
  return `${res.status} ${short}`;
}

const cases = [
  ['GET', '/appointments'],
  ['GET', '/appointments/101'],
  ['GET', '/appointments/102'],
  ['GET', '/appointments/summary'],
  ['PATCH', '/appointments/101', { notes: 'x' }],
  ['PATCH', '/appointments/102', { notes: 'x' }],
];
for (const [method, url, body] of cases) {
  console.log(`${method} ${url}`);
  console.log('   old', await call('http://localhost:4101', method, url, body));
  console.log('   new', await call('http://localhost:4102', method, url, body));
}

