import { createRequire } from 'node:module';
import { readFileSync, readdirSync } from 'node:fs';
const R = process.argv[2];
const require = createRequire(R + '/apps/api/package.json');
const Database = require('better-sqlite3');
const db = new Database(':memory:');
for (const f of readdirSync(R + '/apps/api/drizzle').filter(f => f.endsWith('.sql')).sort())
  for (const st of readFileSync(R + '/apps/api/drizzle/' + f, 'utf8').split('--> statement-breakpoint')) db.exec(st);
console.log('sqlite', db.prepare('select sqlite_version() v').get().v);
const ins = db.prepare(`INSERT INTO appointments (customer_id, treatment_id, starts_at, status, price, created_at) VALUES (1,1,?,'pending',10,0)`);
const sel = db.prepare('SELECT starts_at_utc v FROM appointments WHERE id=?');
const conv = (s) => sel.get(ins.run(s).lastInsertRowid).v;
const fmt = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit', hourCycle:'h23' });
const wallOf = (t) => fmt.format(new Date(t)).slice(0,16);
const pad = (n) => String(n).padStart(2,'0');
let n=0, diffs=[], gaps=[], amb=[];
const tx = db.transaction(() => {
for (let y=2020;y<=2040;y++) {
  const start = Date.UTC(y,0,1), end = Date.UTC(y+1,0,1);
  for (let t=start;t<end;t+=60000) {
    const d = new Date(t);
    // every minute in March 20-Apr 2 and Oct 20-Nov 2, otherwise every 30 minutes
    const m=d.getUTCMonth(), day=d.getUTCDate();
    const dense = (m===2&&day>=20)||(m===3&&day<=2)||(m===9&&day>=20)||(m===10&&day<=2);
    if (!dense && d.getUTCMinutes()%30) continue;
    const wall = `${y}-${pad(m+1)}-${pad(day)} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}`;
    const cands = [t-3600000, t-7200000].filter(c => wallOf(c)===wall).map(c=>new Date(c).toISOString());
    const got = conv(wall); n++;
    if (cands.length===0) gaps.push([wall,got]);
    else if (cands.length===2) amb.push([wall,got,cands]);
    else if (cands[0]!==got) diffs.push([wall,got,cands[0]]);
  }
}});
tx();
console.log('checked', n, 'unambiguous diffs', diffs.length, diffs.slice(0,10));
console.log('gap count', gaps.length, 'sample', gaps.filter(g=>g[0].startsWith('2026')).filter((_,i,a)=>i===0||i===a.length-1));
const gapKinds = new Set(gaps.map(([w,g]) => { const asUtc = Date.parse(w.replace(' ','T')+':00Z'); return (asUtc - Date.parse(g))/3600000; }));
console.log('gap offsets applied (h):', [...gapKinds]);
const ambKinds = new Set(amb.map(([w,g,c]) => c.indexOf(g)===0 ? 'CET(+1, later/second)' : c.indexOf(g)===1 ? 'CEST(+2, earlier/first)' : 'neither'));
console.log('amb count', amb.length, [...ambKinds], amb.filter(a=>a[0].startsWith('2026')).filter((_,i,a)=>i===0||i===a.length-1));
console.log('--- formats');
for (const s of ['2026-10-06T09:00:00.000Z','2026-10-06T09:00:00Z','2026-10-06T09:00Z','2026-10-06T11:00:00+02:00','2026-10-06T11:00:00+0200','2026-10-06T11:00+02:00','2026-10-06T09:00:00','2026-10-06T09:00','2026-10-06','2026-10-06 15:00:00','2026-10-06 15:00:00.000','2026-10-06 15:00Z','2026-10-06 15:00','2026-10-06T09:00:00.123456Z','2026-10-06T09:00:00.999Z','2026-10-06T09:00:60Z','','garbage','next tuesday','2026-13-45 99:99','2026-02-30 10:00','2026-10-06 24:00','2026-10-6','Oct 6, 2026 10:00','0000-01-01 00:00','9999-12-31 23:59','1759300000000','now','12:00',' 2026-10-06 15:00','2026-10-06 15:00 ','2026-10-06T9:00:00Z','2026-10-06t09:00:00z','20261006'])
  console.log(JSON.stringify(s).padEnd(34), '->', conv(s));
console.log('--- plan');
console.log(db.prepare('EXPLAIN QUERY PLAN SELECT * FROM appointments ORDER BY starts_at_utc, id').all().map(r=>r.detail));
console.log(db.prepare("select sql from sqlite_master where name like 'appointments%'").all());

