21 │ /** Returns how far the venue clock is ahead of UTC at an instant, in milliseconds. */
22 │ function venueOffset(instant: number): number {
23 │   const parts = venueClock.formatToParts(new Date(instant));
24 │   const part = (type: Intl.DateTimeFormatPartTypes) => Number(parts.find((p) => p.type === type)?.value);
25 │   const venueClockAsUtc = Date.UTC(part('year'), part('month') - 1, part('day'), part('hour'), part('minute'), part('second'));
26 │   // The clock has no milliseconds, so compare whole seconds.
27 │   return venueClockAsUtc - Math.floor(instant / 1000) * 1000;
28 │ }
