// Live requests that check claims of NOTES.md.
// 4101: the API of the initial commit. 4102: the API at HEAD. 4103: the API at HEAD with API_KEY=secret.
import { execFileSync } from 'node:child_process';
import path from 'node:path';

const INITIAL = 'http://localhost:4101';
const HEAD = 'http://localhost:4102';
const KEYED = 'http://localhost:4103';
const here = import.meta.dirname;

async function call(base, method, url, body, raw, headers = {}) {
  const init = { method, headers: { ...headers } };
  if (raw !== undefined) {
    init.body = raw;
    init.headers['content-type'] = 'application/json';
  } else if (body !== undefined) {
    init.body = JSON.stringify(body);
    init.headers['content-type'] = 'application/json';
  }
  const res = await fetch(base + url, init);
  const text = await res.text();
  let json;
  try {
    json = JSON.parse(text);
  } catch {
    json = text;
  }
  return { status: res.status, body: json };
}
const show = (r, max = 230) => `${r.status} ${JSON.stringify(r.body).slice(0, max)}`;
const head = (title) => console.log(`\n## ${title}`);

head('Error bodies: initial commit and HEAD');
for (const [method, url, body, raw] of [
  ['POST', '/customers', undefined, '{bad'],
  ['GET', '/nope'],
  ['GET', "/customers?search='"],
  ['GET', '/customers/abc'],
  ['POST', '/customers', {}],
  ['POST', '/treatments', {}],
  ['POST', '/appointments', {}],
  ['GET', '/appointments/999'],
]) {
  console.log(`${method} ${url} ${raw ?? (body ? JSON.stringify(body) : '')}`);
  console.log('   initial', show(await call(INITIAL, method, url, body, raw)));
  console.log('   head   ', show(await call(HEAD, method, url, body, raw)));
}

head('List query (all at HEAD)');
for (const q of [
  '?date=2026-10-05', '?foo=1', '?page=1e1', '?page=1.5', '?page=', '?status=', '?status=a&status=b', '?status=canceled',
  '?page=0', '?pageSize=101', '?sortBy=id', '?from=2026-10-09&to=2026-10-05', '?status=cancelled&pageSize=100', '?page=99',
]) {
  const r = await call(HEAD, 'GET', '/appointments' + q);
  const brief = r.status === 200 ? `items=${r.body.items.length} ids=${r.body.items.map((a) => a.id)} page=${r.body.page} pageSize=${r.body.pageSize} total=${r.body.total}` : '';
  console.log(`GET /appointments${q} -> ${r.status} ${brief}`);
}
const asc = (await call(HEAD, 'GET', '/appointments?sortBy=price&sortDir=asc&pageSize=100')).body.items.map((a) => a.id);
const desc = (await call(HEAD, 'GET', '/appointments?sortBy=price&sortDir=desc&pageSize=100')).body.items.map((a) => a.id);
console.log('price asc ', asc.join(','));
console.log('price desc', desc.join(','), 'exact reverse:', asc.slice().reverse().join(',') === desc.join(','));

head('Ids');
for (const [method, url] of [['GET', '/appointments/1e0'], ['GET', '/appointments/0x1'], ['GET', '/appointments/1.0'], ['DELETE', '/appointments/1e0'], ['GET', '/appointments/1/audit'], ['GET', '/appointments/1e0/audit'], ['GET', '/staff/1e0']]) {
  console.log(`${method} ${url} -> ${(await call(HEAD, method, url)).status}`);
}
console.log('GET /appointments/1 ->', (await call(HEAD, 'GET', '/appointments/1')).status, '(appointment 1 still exists)');

head('Start time input');
for (const startsAt of ['2026-11-05 09:00', '2026-11-05T09:00', '2026-11-05', '2026-11-05T09:00:00+02:00', '2026-11-06T09:00:00Z']) {
  const r = await call(HEAD, 'POST', '/appointments', { customerId: 8, treatmentId: 2, startsAt });
  console.log(`POST startsAt=${startsAt} -> ${r.status} ${r.status === 201 ? r.body.startsAt : ''}`);
}

head('Status rules');
console.log('PATCH 6 (cancelled) status=confirmed ->', (await call(HEAD, 'PATCH', '/appointments/6', { status: 'confirmed' })).status);
console.log('PATCH 6 (cancelled) status=pending   ->', (await call(HEAD, 'PATCH', '/appointments/6', { status: 'pending' })).status);
console.log('PATCH 6 (cancelled) status=cancelled ->', (await call(HEAD, 'PATCH', '/appointments/6', { status: 'cancelled' })).status);
console.log('PATCH 6 (cancelled) notes            ->', show(await call(HEAD, 'PATCH', '/appointments/6', { notes: 'n' }), 90));
console.log('PATCH 11 (legacy canceled) status=confirmed ->', (await call(HEAD, 'PATCH', '/appointments/11', { status: 'confirmed' })).status);
console.log('PATCH 13 (completed) status=pending  ->', (await call(HEAD, 'PATCH', '/appointments/13', { status: 'pending' })).status, '(only a change away from cancelled is blocked)');
console.log('PATCH 999 invalid body ->', (await call(HEAD, 'PATCH', '/appointments/999', { status: 'banana' })).status, '(API)');
console.log('GET 11 ->', show(await call(HEAD, 'GET', '/appointments/11'), 120));
console.log('summary ->', show(await call(HEAD, 'GET', '/appointments/summary')));

head('Audit trail');
console.log('seeded 2 ->', show(await call(HEAD, 'GET', '/appointments/2/audit')));
console.log('never existed 999 ->', (await call(HEAD, 'GET', '/appointments/999/audit')).status);
const created = await call(HEAD, 'POST', '/appointments', { customerId: 7, treatmentId: 2, startsAt: '2026-12-01T09:00:00Z', notes: 'first' });
const id = created.body.id;
await call(HEAD, 'PATCH', `/appointments/${id}`, { notes: 'first', status: 'pending' });
await call(HEAD, 'PATCH', `/appointments/${id}`, { status: 'confirmed' });
console.log('DELETE with a JSON content type and no body ->', (await call(HEAD, 'DELETE', `/appointments/${id}`, undefined, undefined, { 'content-type': 'application/json' })).status);
console.log('second DELETE ->', (await call(HEAD, 'DELETE', `/appointments/${id}`)).status);
console.log('GET deleted ->', (await call(HEAD, 'GET', `/appointments/${id}`)).status, 'PATCH deleted ->', (await call(HEAD, 'PATCH', `/appointments/${id}`, { notes: 'x' })).status);
const trail = await call(HEAD, 'GET', `/appointments/${id}/audit`);
console.log('trail of a created, updated and deleted appointment ->', trail.status);
for (const entry of trail.body) console.log('   ', JSON.stringify(entry));
await call(HEAD, 'PATCH', '/appointments/11', { notes: 'legacy note' });
await call(HEAD, 'DELETE', '/appointments/12');
console.log('legacy 11 after a notes change ->', show(await call(HEAD, 'GET', '/appointments/11/audit'), 400));
console.log('legacy 12 after a delete       ->', show(await call(HEAD, 'GET', '/appointments/12/audit'), 400));

head('Staff');
console.log('POST Zoe  ->', show(await call(HEAD, 'POST', '/staff', { name: '  Zoe  ', email: '  Anna@X.com ' })));
console.log('POST same email, lower case ->', (await call(HEAD, 'POST', '/staff', { name: 'other', email: 'anna@x.com' })).status);
console.log('POST anna ->', (await call(HEAD, 'POST', '/staff', { name: 'anna', email: 'b@x.com' })).status);
console.log('POST Bob  ->', (await call(HEAD, 'POST', '/staff', { name: 'Bob', email: 'c@x.com' })).status);
console.log('GET /staff order ->', (await call(HEAD, 'GET', '/staff')).body.map((s) => s.name).join(', '));
console.log('PATCH empty body ->', (await call(HEAD, 'PATCH', '/staff/1', {})).status, ' PATCH blank name ->', (await call(HEAD, 'PATCH', '/staff/1', { name: '   ' })).status);

head('Legacy special hours (rows written to the database of HEAD)');
execFileSync('sqlite3', [
  path.join(here, 'head.db'),
  "INSERT INTO appointments (id, customer_id, treatment_id, starts_at, status, price, notes, created_at) VALUES " +
    "(201, 1, 2, '2026-03-29 02:30', 'pending', 10, NULL, 1), (202, 2, 2, '2026-10-25 02:30', 'pending', 10, NULL, 2);",
]);
console.log('legacy 2026-03-29 02:30 ->', (await call(HEAD, 'GET', '/appointments/201')).body.startsAt);
console.log('legacy 2026-10-25 02:30 ->', (await call(HEAD, 'GET', '/appointments/202')).body.startsAt);

head('API key');
console.log('no key      ->', show(await call(KEYED, 'GET', '/appointments')));
console.log('wrong key   ->', show(await call(KEYED, 'GET', '/appointments', undefined, undefined, { 'x-api-key': 'nope' })));
console.log('health, no key ->', show(await call(KEYED, 'GET', '/health')));
console.log('right key   ->', (await call(KEYED, 'GET', '/appointments', undefined, undefined, { 'x-api-key': 'secret' })).status);

